import os
import time
import hmac
import hashlib
import threading
from flask import Flask, request, jsonify, g
from functools import wraps
import bcrypt
import secrets

app = Flask(__name__)
app.secret_key = os.urandom(32)

# In-memory stores
USERS_DB = {
    'admin': bcrypt.hashpw(b'SecureP@ss99!', bcrypt.gensalt()).decode(),
    'user1': bcrypt.hashpw(b'UserPass123!', bcrypt.gensalt()).decode(),
}

class TokenStore:
    """Thread-safe token store with automatic rotation."""

    def __init__(self):
        self._tokens = {}  # token -> {user, created, last_used}
        self._user_tokens = {}  # user -> set of active tokens
        self._lock = threading.Lock()
        self.TOKEN_LIFETIME = 3600  # 1 hour
        self.ROTATION_WINDOW = 300  # 5 min grace period
        self.MAX_TOKENS_PER_USER = 5

    def create_token(self, username):
        """Create a new session token for user."""
        with self._lock:
            token = secrets.token_hex(32)
            self._tokens[token] = {
                'user': username,
                'created': time.time(),
                'last_used': time.time(),
                'rotated_from': None
            }
            if username not in self._user_tokens:
                self._user_tokens[username] = set()
            self._user_tokens[username].add(token)
            self._enforce_max_tokens(username)
            return token

    def _enforce_max_tokens(self, username):
        """Remove oldest tokens if user exceeds max."""
        tokens = self._user_tokens.get(username, set())
        if len(tokens) > self.MAX_TOKENS_PER_USER:
            sorted_tokens = sorted(
                tokens,
                key=lambda t: self._tokens.get(t, {}).get('created', 0)
            )
            for old_token in sorted_tokens[:len(tokens) - self.MAX_TOKENS_PER_USER]:
                self._invalidate_token_internal(old_token)

    def _invalidate_token_internal(self, token):
        """Remove token without acquiring lock (caller must hold lock)."""
        if token in self._tokens:
            user = self._tokens[token]['user']
            del self._tokens[token]
            if user in self._user_tokens:
                self._user_tokens[user].discard(token)

    def validate_token(self, token):
        """Validate token and return username if valid."""
        with self._lock:
            if token not in self._tokens:
                return None
            entry = self._tokens[token]
            now = time.time()
            # Check if token has expired
            if now - entry['created'] > self.TOKEN_LIFETIME:
                self._invalidate_token_internal(token)
                return None
            entry['last_used'] = now
            return entry['user']

    def rotate_token(self, old_token):
        """Rotate token: create new one, invalidate old."""
        with self._lock:
            if old_token not in self._tokens:
                return None

            token_data = self._tokens[old_token]
            username = token_data['user']
            now = time.time()

            # Check if rotation is needed (token older than half lifetime)
            if now - token_data['created'] < self.TOKEN_LIFETIME / 2:
                return old_token  # No rotation needed yet

            # Create new token and link to old
            new_token = secrets.token_hex(32)
            self._tokens[new_token] = {
                'user': username,
                'created': now,
                'last_used': now,
                'rotated_from': old_token
            }
            if username not in self._user_tokens:
                self._user_tokens[username] = set()
            self._user_tokens[username].add(new_token)
            # Old token remains valid during grace period
            self._enforce_max_tokens(username)
            return new_token

    def invalidate_user_tokens(self, username):
        """Invalidate all tokens for a user (logout all)."""
        with self._lock:
            tokens = list(self._user_tokens.get(username, set()))
            for token in tokens:
                self._invalidate_token_internal(token)


token_store = TokenStore()

# HMAC key for request signing (defense in depth)
REQUEST_SIGNING_KEY = os.urandom(32)


def compute_request_signature(token, timestamp, body):
    """Compute HMAC signature for request integrity."""
    msg = f"{token}:{timestamp}:{body}".encode()
    return hmac.new(REQUEST_SIGNING_KEY, msg, hashlib.sha256).hexdigest()


def verify_request_signature(token, timestamp, body, signature):
    """Verify request signature with timing-safe comparison."""
    expected = compute_request_signature(token, timestamp, body)
    return hmac.compare_digest(expected, signature)


def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        auth_header = request.headers.get('Authorization', '')
        if not auth_header.startswith('Bearer '):
            return jsonify({'error': 'Missing authorization'}), 401

        token = auth_header[7:]
        username = token_store.validate_token(token)
        if username is None:
            return jsonify({'error': 'Invalid or expired token'}), 401

        g.current_user = username
        g.auth_token = token

        # Attempt token rotation on each request
        new_token = token_store.rotate_token(token)
        if new_token and new_token != token:
            g.new_token = new_token
        else:
            g.new_token = None

        return f(*args, **kwargs)
    return decorated


@app.after_request
def add_security_headers(response):
    response.headers['X-Content-Type-Options'] = 'nosniff'
    response.headers['X-Frame-Options'] = 'DENY'
    response.headers['Strict-Transport-Security'] = 'max-age=31536000; includeSubDomains'

    # Include rotated token in response header if applicable
    if hasattr(g, 'new_token') and g.new_token:
        response.headers['X-New-Token'] = g.new_token

    return response


@app.route('/auth/login', methods=['POST'])
def login():
    data = request.get_json(silent=True)
    if not data or 'username' not in data or 'password' not in data:
        return jsonify({'error': 'Missing credentials'}), 400

    username = data['username']
    password = data['password']

    # Validate types to avoid unhandled errors / type confusion
    if not isinstance(username, str) or not isinstance(password, str):
        return jsonify({'error': 'Invalid credentials format'}), 400

    password = password.encode()

    if username not in USERS_DB:
        # Constant-time dummy check to prevent user enumeration
        bcrypt.checkpw(password, bcrypt.hashpw(b'dummy', bcrypt.gensalt()))
        return jsonify({'error': 'Invalid credentials'}), 401

    stored_hash = USERS_DB[username].encode()
    if not bcrypt.checkpw(password, stored_hash):
        return jsonify({'error': 'Invalid credentials'}), 401

    token = token_store.create_token(username)
    return jsonify({'token': token, 'expires_in': token_store.TOKEN_LIFETIME})


@app.route('/auth/logout', methods=['POST'])
@require_auth
def logout():
    token_store.invalidate_user_tokens(g.current_user)
    return jsonify({'message': 'Logged out from all sessions'})


@app.route('/api/profile', methods=['GET'])
@require_auth
def get_profile():
    return jsonify({
        'username': g.current_user,
        'role': 'admin' if g.current_user == 'admin' else 'user'
    })


@app.route('/api/admin/users', methods=['GET'])
@require_auth
def list_users():
    if g.current_user != 'admin':
        return jsonify({'error': 'Forbidden'}), 403
    return jsonify({'users': list(USERS_DB.keys())})


@app.route('/api/admin/revoke/<username>', methods=['POST'])
@require_auth
def revoke_user(username):
    if g.current_user != 'admin':
        return jsonify({'error': 'Forbidden'}), 403
    if username not in USERS_DB:
        return jsonify({'error': 'User not found'}), 404
    token_store.invalidate_user_tokens(username)
    return jsonify({'message': f'All sessions revoked for {username}'})


if __name__ == '__main__':
    app.run(host='127.0.0.1', port=5000)
